function cylinder(g,rt,rb,h,x,y,z,mat,rx=0,rz=0){const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,24),mat);m.position.set(x,y,z);m.rotation.set(rx,0,rz);g.add(m);return m}
