function valveModel(){const g=new THREE.Group(),steel=material(0xc4cecb,.88,.22),dark=material(0x41454c,.65,.3);cylinder(g,.65,.65,2.5,0,.7,0,steel,0,Math.PI/2);for(const x of [-1.35,1.35]){cylinder(g,.92,.92,.18,x,.7,0,steel,0,Math.PI/2);for(let i=0;i<8;i++){const a=i*Math.PI/4;sphere(g,.09,x,.7+.73*Math.cos(a),.73*Math.sin(a),dark)}}box(g,.85,.15,.85,0,1.3,0,steel);for(const x of [-.35,.35])box(g,.12,1.3,.12,x,2,0,steel);cylinder(g,.12,.12,1.6,0,2.1,0,steel);cylinder(g,.86,.86,.6,0,3,0,dark);cylinder(g,.95,.95,.12,0,2.65,0,steel);box(g,.55,.6,.38,.65,2.1,.35,dark);g.scale.setScalar(1.35);return g}
function factory(){const g=new THREE.Group(),base=material(0x8ba69d,.12,.85),road=material(0x5c6265,.1,.8),wall=material(0xdce4dd,.3,.5),roof=material(0x6f8e8b,.5,.4),glass=material(0x8ed7d1,.6,.2);box(g,30,.25,21,0,-.4,0,base);box(g,29,.03,2.4,0,-.23,0,road);box(g,1.8,.03,19,-12,-.23,0,road);const areas=['Facility','Process','Packaging','Quality','Maintenance','Workforce Mgmt'];areas.forEach((name,i)=>{const group=new THREE.Group(),x=-8+(i%3)*8,z=i<3?-5:5,h=i===1?2.5:1.7;group.userData={area:name};group.position.set(x,0,z);box(group,6,h,5,0,h/2,0,wall);box(group,6.2,.2,5.2,0,h+.1,0,roof);for(let xx=-2;xx<=2;xx+=1)for(const zz of [-2.51,2.51])box(group,.7,.7,.025,xx,h*.6,zz,glass);for(const xx of [-2,0,2])box(group,1,.15,2,xx,h+.25,0,glass);if(i===1){cylinder(group,.5,.5,2,-2,h+1.1,0,wall);cylinder(group,.4,.4,2.6,-.8,h+1.3,0,wall)}if(window.op?.located&&name===window.op.locationArea){const light=new THREE.Mesh(new THREE.RingGeometry(.5,.8,32),new THREE.MeshBasicMaterial({color:0xffce92,side:THREE.DoubleSide}));light.rotation.x=-Math.PI/2;light.position.set(0,h+.3,0);group.add(light)}g.add(group)});for(let i=0;i<12;i++){const x=-14+i*2.5;box(g,.12,1,.12,x,.4,-9,wall);sphere(g,.6,x,1.1,-9,material(0x7fae93,.05,.8))}return g}
function studioEnvironment(){const c=document.createElement('canvas');c.width=512;c.height=256;const x=c.getContext('2d');const gradient=x.createLinearGradient(0,0,0,256);gradient.addColorStop(0,'#e9e5df');gradient.addColorStop(.48,'#afa4ae');gradient.addColorStop(.52,'#706570');gradient.addColorStop(1,'#332c38');x.fillStyle=gradient;x.fillRect(0,0,512,256);x.fillStyle='#fffdf5';x.fillRect(35,25,70,140);x.fillRect(260,20,85,120);x.fillStyle='#c5f6e3';x.fillRect(400,45,40,115);const texture=new THREE.CanvasTexture(c);texture.mapping=THREE.EquirectangularReflectionMapping;texture.colorSpace=THREE.SRGBColorSpace;return texture}
function personalizeFactoryModel(g){const variant=window.currentFactoryModelVariant?.()||0;if(!variant)return g;const plans={1:{Facility:[10,-6],Process:[0,-6],Packaging:[9,1],Quality:[-8,-1],Maintenance:[7,6],'Workforce Mgmt':[-6,6]},2:{Facility:[10,-6],Process:[-3,-5],Packaging:[8,1],Quality:[-8,3],Maintenance:[8,7],'Workforce Mgmt':[0,7]},3:{Facility:[10,-6],Process:[-1,-3],Packaging:[8,2],Quality:[-8,6],Maintenance:[5,7],'Workforce Mgmt':[-9,-4]}};for(const building of g.children.filter(o=>o.userData.area)){const area=building.userData.area,p=plans[variant]?.[area];if(p)building.position.set(p[0],0,p[1]);if(variant===1){if(area==='Process')building.scale.set(1.45,1,1);if(area==='Workforce Mgmt')building.scale.y=1.4;}if(variant===2&&['Quality','Workforce Mgmt'].includes(area)){const curved=new THREE.Mesh(new THREE.CylinderGeometry(2.8,2.8,1.8,40,1,false,0,Math.PI*1.5),material(0x80c1cb,.55,.22));curved.position.set(0,.9,1);building.add(curved);cylinder(building,2.9,2.9,.12,0,1.86,1,material(0xd8ddd7,.4,.4))}if(variant===3){if(area==='Process')building.scale.set(1.45,1.45,1.2);if(area==='Packaging')building.scale.set(1.1,1,1.2);if(area==='Facility')for(let i=0;i<3;i++)cylinder(building,.47,.47,2.3,-1.5+i*1.35,2.7,0,material(0xc8ceca,.9,.2))}}if(variant===1)box(g,5,.06,3,0,-.21,2,material(0x94c5a7,.1,.8));return g}
function attach(el){const kind=el.dataset.model,index=Number(el.dataset.index||0);try{const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.5;renderer.setClearColor(0,0);const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(34,1,.1,150),model=kind==='factory'?personalizeFactoryModel(factory()):kind==='packaging'?packaging(index):kind==='valve'?valveModel():pump(kind);scene.environment=studioEnvironment();scene.environmentIntensity=.75;scene.add(model);scene.add(new THREE.HemisphereLight(0xfff2f7,0x7c6e7b,3));const key=new THREE.DirectionalLight(0xffffff,4);key.position.set(-5,10,10);scene.add(key);const rim=new THREE.DirectionalLight(0xa5ffe1,2);rim.position.set(5,5,-8);scene.add(rim);const fill=new THREE.DirectionalLight(0xf1c3df,2);fill.position.set(-8,1,-4);scene.add(fill);const distance=kind==='factory'?42:kind==='packaging'?20:13;camera.position.set(distance*.55,distance*.47,distance*.7);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,kind==='factory'?0:1.3,0);controls.enableDamping=true;controls.dampingFactor=.12;controls.enablePan=false;controls.minDistance=distance*.5;controls.maxDistance=distance*1.8;controls.maxPolarAngle=Math.PI*.47;controls.update();const start=camera.position.clone();el.appendChild(renderer.domElement);el.classList.add('model-ready');renderer.domElement.setAttribute('aria-label','3D '+kind+' model. Drag to orbit and scroll to zoom.');renderer.domElement.setAttribute('role','img');const resize=()=>{const r=el.getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()};const observer=new ResizeObserver(resize);observer.observe(el);resize();let down=null;renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(kind!=='factory'||!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);for(const hit of ray.intersectObjects(model.children,true)){let node=hit.object;while(node&&!node.userData.area)node=node.parent;if(node?.userData.area){window.go(node.userData.area);break}}});active.push({el,renderer,scene,camera,controls,observer,kind,start})}catch{el.classList.add('model-unavailable');const hint=el.querySelector('.model-hint');if(hint)hint.textContent='3D unavailable on this device · schematic view'}}
window.mountOperationsModels=()=>{for(const el of document.querySelectorAll('.model-view:not(.model-ready):not(.model-unavailable)'))attach(el)};
window.disposeOperationsModels=()=>{for(const a of active){a.observer.disconnect();a.controls.dispose();a.scene.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose()}});a.scene.environment?.dispose();a.renderer.dispose();a.renderer.forceContextLoss();a.renderer.domElement.remove()}active=[]};
